/**
 * @fileoverview Test the usage of a private property
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-private-property-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-private-property-usage', rule, {

    valid: [
        {
            code: `
                // fields can be both a config and a property
                // it is ok to use as a config but not as a property since the property is private 
                // and thus can't be counted on to exist in future versions of the framework
                Ext.define('AddressBook.model.Contact', {
                    extend: 'Ext.data.Model',
                    fields: [
                        'firstName',
                        'lastName',
                        'headshot',
                        'title',
                        'telephone',
                        'city',
                        'state',
                        'country',
                        'latitude',
                        'longitude'
                    ]
                });
            `
        }
    ],

    invalid: [
        {
            settings: {
                toolkit: 'classic',
                fromVersion: '4.0',
                toVersion: '7.9'
            },
            code: `
                // fields can be both a config and a property
                // and when a property, it is supposed to be a readonly private property
                Ext.define('AddressBook.model.Contact', {
                    extend: 'Ext.data.Model',

                    // should be valid
                    fields: [
                        'firstName', 'lastName'
                    ],
                    contructor: function () {
                        var me = this;
                        
                        // should be invalid
                        var fLen = this.fields.length;

                        // should be invalid
                        var fLen2 = me.fields.length;

                        // should be invalid
                        this.fields = [
                            'firstName',
                            'lastName',
                            'headshot',
                            'title',
                            'telephone',
                            'city',
                            'state',
                            'country',
                            'latitude',
                            'longitude'
                        ];

                        // should be invalid
                        this.fields.concat([]);

                        // should be invalid
                        me.fields.join('');
                    }
                });
            `,
            errors: [
                { message: /Usage of private property 'fields' found for 'Ext.data.Model'/ },
                { message: /Usage of private property 'fields' found for 'Ext.data.Model'/ },
                { message: /Usage of private property 'fields' found for 'Ext.data.Model'/ },
                { message: /Usage of private property 'fields' found for 'Ext.data.Model'/ },
                { message: /Usage of private property 'fields' found for 'Ext.data.Model'/ }
            ]
        },
        {
            settings: {
                extjs: {
                    version: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomDataBatch', {
                    extend: 'Ext.data.Batch',
                    runOperation: function () {
                        this.complete = true;
                    }
                });
                Ext.define('MyCustomDataBatch', {
                    extend: 'Ext.data.Batch',
                    runOperation: function () {
                        var me = this;
                        me.complete = true;
                    }
                });
                Ext.define('MyCustomDataBatch', {
                    extend: 'Ext.data.Batch',
                    complete: false
                });
            `,
            errors: [
                { 
                    message: /Usage of private property 'complete' found for 'Ext.data.Batch'/,
                    type: 'MemberExpression'
                },
                { 
                    message: /Usage of private property 'complete' found for 'Ext.data.Batch'/,
                    type: 'MemberExpression'
                },
                { 
                    message: /Usage of private property 'complete' found for 'Ext.data.Batch'/,
                    type: 'Property'
                }
            ]
        }
    ]
});
